package com.example.basekmp.data

object ExtraTranslations {
    private val keyList: Array<String> by lazy { keys() }
    val byLanguage: Map<String, Map<String, String>> by lazy {
        mapOf(
            "de" to build(de()),
            "es" to build(es()),
            "fr" to build(fr()),
            "it" to build(it()),
            "pt" to build(pt()),
            "vi" to build(vi()),
            "tr" to build(tr()),
            "ru" to build(ru()),
            "ar" to build(ar()),
            "ja" to build(ja()),
            "zh" to build(zh()),
            "ko" to build(ko()),
            "th" to build(th()),
            "ur" to build(ur()),
            "hi" to build(hi()),
        )
    }

    private fun build(values: Array<String>): Map<String, String> {
        val keys = keyList
        val map = HashMap<String, String>(keys.size)
        for (i in keys.indices) {
            if (i < values.size) {
                map[keys[i]] = values[i]
            }
        }
        return map
    }

